Lesson: V-M3-L03 - "Formatarea paragrafelor - aliniere, spatiere, indentare" (Grade V, Romanian curriculum)

Knowledge content:
{
  "levels": [
    {
      "level": "general",
      "concepts": [
        "Paragraful este un grup de propozitii despre aceeași idee",
        "Formatarea paragrafului controleaza cum arată blocul de text, nu literele individuale"
      ]
    },
    {
      "level": "intermediate",
      "concepts": [
        "Alinierea (Alignment): stanga, centru, dreapta, justify (ambele margini)",
        "Spatierea (Spacing): distanta dintre rânduri și dintre paragrafe",
        "Indentarea (Indent): spatiul de la marginea paginii până la inceputul textului"
      ]
    },
    {
      "level": "specific",
      "concepts": [
        "Align Left (Ctrl+L): textul începe de la stanga - folosit pentru text normal",
        "Center (Ctrl+E): textul e centrat - folosit pentru titluri",
        "Align Right (Ctrl+R): textul se termina la dreapta - folosit pentru date, semnaturi",
        "Justify (Ctrl+J): textul e aliniat la ambele margini - folosit în carti și documente oficiale",
        "Line Spacing: 1.0 (compact), 1.5 (normal), 2.0 (spatios - pentru corectare)",
        "First Line Indent: alineatul traditional la inceputul paragrafului"
      ]
    }
  ]
}

Instructional content:
{
  "hook": {
    "duration_minutes": 3,
    "activity": "Aratati o pagină dintr-o carte și una dintr-un caiet de elev. Intrebati: Ce diferente vedeti? De ce cartea arată mai 'profesionala'? Raspunsul e în formatarea paragrafelor!",
    "connection_to_prior": "În lectia trecuta am învățat să formatam caracterele (Bold, Italic). Acum învățăm să formatam paragrafele intregi!"
  },
  "micro_lecture": {
    "duration_minutes": 10,
    "key_terms": [
      {
        "term": "Aliniere (Alignment)",
        "definition": "Poziția textului față de marginile paginii",
        "analogy": "Ca soldatii în rând - pot sta aliniati la stanga, la mijloc, la dreapta, sau ocupand tot spatiul"
      },
      {
        "term": "Justify (Aliniere stanga-dreapta)",
        "definition": "Textul este aliniat perfect la ambele margini, ca în carti",
        "analogy": "Ca un gard perfect drept pe ambele parti"
      },
      {
        "term": "Line Spacing (Spatiere rânduri)",
        "definition": "Distanta verticala dintre randurile de text",
        "analogy": "Ca distanta dintre randurile din caiet - liniate ingust sau larg"
      },
      {
        "term": "Indent (Indentare/Alineat)",
        "definition": "Spatiul lasat la inceputul unui paragraf sau la toata marginea",
        "analogy": "Ca atunci când incepi un paragraf nou și lasi un 'deget' spațiu în caiet"
      },
      {
        "term": "First Line Indent",
        "definition": "Doar primul rând al paragrafului are alineat, restul sunt la margine",
        "analogy": "Stilul clasic din carti - primul rând începe mai în interior"
      }
    ],
    "explain_like_im_12": "Dacă formatarea caracterelor e machiajul textului, formatarea paragrafelor e mobilarea camerei. Poti avea cele mai frumoase lucruri, dar dacă sunt aruncate dezordonat, camera arată rau. La fel, paragrafele bine aranjate fac documentul placut și profesional.",
    "visual_aids": [
      "4 exemple de aliniere: stanga, centru, dreapta, justify - același text",
      "Comparatie: spatiere 1.0 vs 1.5 vs 2.0",
      "Demonstratie live: First Line Indent"
    ]
  },
  "practice_guided": {
    "duration_minutes": 15,
    "tasks": [
      {
        "task": "Experimenteaza cu alinierea",
        "steps": [
          "Deschide un document nou și scrie un paragraf de 3-4 propozitii",
          "Pune cursorul în paragraf (nu trebuie să selectezi tot)",
          "Apasă Ctrl+L - observa alinierea la stanga",
          "Apasă Ctrl+E - observa centrarea",
          "Apasă Ctrl+R - observa alinierea la dreapta",
          "Apasă Ctrl+J - observa alinierea justify"
        ],
        "teacher_support": "Profesorul demonstreaza pe proiector, explicand când se folosește fiecare"
      },
      {
        "task": "Seteaza spatierea dintre rânduri",
        "steps": [
          "Selectează paragraful tau",
          "Mergi la Home > Line Spacing (sau Format > Paragraph)",
          "Alege 1.5 lines - observa cum se mareste spatiul",
          "Schimbă la 2.0 lines - și mai spatios",
          "Revino la 1.15 sau 1.5 - optim pentru citire"
        ],
        "teacher_support": "Arată unde se găsește optiunea în meniu și pe bara de instrumente"
      },
      {
        "task": "Adaugă First Line Indent",
        "steps": [
          "Scrie încă un paragraf sub primul",
          "Selectează ambele paragrafe",
          "Format > Paragraph > Indentation > Special > First line",
          "Seteaza la 1.27 cm (sau 0.5 inch)",
          "Observa cum fiecare paragraf are acum alineat la început"
        ],
        "teacher_support": "Alternativ: arată metoda cu rigla (ruler) - trage triunghiul de sus"
      }
    ],
    "success_criteria": [
      "Elevul poate schimbă alinierea folosind Ctrl+L/E/R/J",
      "Elevul poate modifică spatierea dintre rânduri",
      "Elevul poate adaugă First Line Indent"
    ]
  },
  "practice_independent": {
    "duration_minutes": 15,
    "levels": {
      "minim": [
        {
          "task": "Scrie un paragraf de 3 propozitii. Fa-l aliniat Justify și cu spatiere 1.5.",
          "expected_output": "Paragraf cu ambele margini drepte și spatiere vizibila între rânduri"
        }
      ],
      "standard": [
        {
          "task": "Creaza o mini-scrisoare cu: antetul aliniat la dreapta (data, oras), corpul scrisorii justify cu First Line Indent, semnatura aliniata la dreapta.",
          "expected_output": "Scrisoare cu 3 secțiuni formatate diferit, aspect profesional"
        }
      ],
      "performanta": [
        {
          "task": "Formatează un eseu complet: titlu centrat bold, 3 paragrafe justify cu First Line Indent 1.27cm, spatiere 1.5, spațiu de 12pt după fiecare paragraf. Salvează ca 'Eseu_paragraf.docx'.",
          "expected_output": "Eseu cu formatare profesionala consistenta"
        }
      ]
    }
  },
  "wrap_up": {
    "duration_minutes": 7,
    "exit_ticket": {
      "minim": [
        "Ce shortcut folosim pentru a centra un text?"
      ],
      "standard": [
        "Care este diferenta dintre Align Left și Justify?"
      ],
      "performanta": [
        "Cum ai formata o scrisoare oficiala? Ce aliniere pentru fiecare parte?"
      ]
    },
    "preview_next": "Saptamana viitoare învățăm despre liste - cum să facem enumerari cu buline sau numere, foarte utile pentru referate!"
  }
}

